export const HYBRID_TEST_IDENTITY_ALIASES = Object.freeze(Object.keys(IDENTITIES));

export function hybridPublicKeyPairFixture(identityAlias) {
  const fixture = IDENTITIES[identityAlias];
  if (!fixture) throw new Error(`unknown hybrid test identity ${identityAlias}`);
  return {
    scheme: fixture.scheme,
    ed25519_public_key_spki_der_base64url: fixture.ed25519_public_key_spki_der_base64url,
    ml_dsa_65_public_key_spki_der_base64url: fixture.ml_dsa_65_public_key_spki_der_base64url,
  };
}

export function hybridPrivateKeyPairFixture(identityAlias) {
  const fixture = IDENTITIES[identityAlias];
  if (!fixture) throw new Error(`unknown hybrid test identity ${identityAlias}`);
  return {
    ed25519_private_key_pkcs8_der_base64url: fixture.ed25519_private_key_pkcs8_der_base64url,
    ml_dsa_65_private_key_pkcs8_der_base64url: fixture.ml_dsa_65_private_key_pkcs8_der_base64url,
  };
}

export function hybridPrincipalFixture(identityAlias, options = {}) {
  const { alias = identityAlias, balance = 0, operator = alias, scopes = ["*"] } = options;
  return {
    alias,
    balance,
    operator,
    scopes: [...scopes],
    ...hybridPublicKeyPairFixture(identityAlias),
  };
}
